 "content": "def transform(grid):
    """Copy the colored pattern around one 5-marker to the other 5-marker."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(markers) != 2:
        return [row[:] for row in grid]

    def has_colored_neighbor(pos):
        r, c = pos
        return any(0 <= r + dr < h and 0 <= c + dc < w and
                   grid[r + dr][c + dc] not in (0, 5)
                   for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)))

    attached = [p for p in markers if has_colored_neighbor(p)]
    if len(attached) != 1:
        return [row[:] for row in grid]
    src = attached[0]
    dst = markers[0] if markers[1] == src else markers[1]
    dr, dc = dst[0] - src[0], dst[1] - src[1]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) == src:
                continue
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
